INSERT INTO conteudo (titulo, categoria, descricao, nivel, fonte) VALUES
    ('Radioterapia no combate ao cancer', 'SAUDE', 'A radioterapia usa radiacao ionizante de forma controlada para destruir celulas tumorais, preservando ao maximo os tecidos saudaveis ao redor.', 'BASICO', 'CNEN');
INSERT INTO conteudo (titulo, categoria, descricao, nivel, fonte) VALUES
    ('Medicina nuclear e exames por imagem', 'SAUDE', 'Radiofarmacos sao administrados ao paciente e emitem radiacao que equipamentos como PET e SPECT captam, gerando imagens do funcionamento dos orgaos.', 'INTERMEDIARIO', 'AIEA');
INSERT INTO conteudo (titulo, categoria, descricao, nivel, fonte) VALUES
    ('Esterilizacao de materiais hospitalares', 'INDUSTRIA', 'Seringas, luvas e outros materiais descartaveis podem ser esterilizados por radiacao gama depois de embalados, sem uso de calor ou produtos quimicos.', 'BASICO', 'CNEN');
INSERT INTO conteudo (titulo, categoria, descricao, nivel, fonte) VALUES
    ('Gamagrafia: inspecionando soldas por dentro', 'INDUSTRIA', 'A gamagrafia usa radiacao para gerar imagens do interior de pecas e soldas, permitindo detectar falhas sem destruir o material.', 'INTERMEDIARIO', 'AIEA');
INSERT INTO conteudo (titulo, categoria, descricao, nivel, fonte) VALUES
    ('Alimentos que duram mais com irradiacao', 'AGRICULTURA', 'A irradiacao de alimentos reduz microrganismos e retarda o amadurecimento, aumentando o prazo de validade sem tornar o alimento radioativo.', 'BASICO', 'CNEN');
INSERT INTO conteudo (titulo, categoria, descricao, nivel, fonte) VALUES
    ('Plantas melhoradas por mutacao induzida', 'AGRICULTURA', 'A radiacao pode provocar pequenas mutacoes em sementes, e os pesquisadores selecionam variedades mais resistentes a pragas, seca ou doencas.', 'AVANCADO', 'AIEA');
INSERT INTO conteudo (titulo, categoria, descricao, nivel, fonte) VALUES
    ('Datacao por carbono-14', 'PESQUISA', 'Medindo a quantidade de carbono-14 restante em restos organicos, cientistas estimam a idade de fosseis e artefatos arqueologicos.', 'INTERMEDIARIO', 'AIEA');
INSERT INTO conteudo (titulo, categoria, descricao, nivel, fonte) VALUES
    ('Reatores de pesquisa produzem radioisotopos', 'PESQUISA', 'Reatores de pesquisa geram neutrons usados em estudos cientificos e na producao de radioisotopos aplicados em diagnosticos e tratamentos medicos.', 'AVANCADO', 'CNEN');
INSERT INTO conteudo (titulo, categoria, descricao, nivel, fonte) VALUES
    ('Como uma usina nuclear gera eletricidade', 'ENERGIA', 'Na fissao nuclear, o calor liberado aquece agua e produz vapor, que movimenta uma turbina ligada a um gerador de eletricidade.', 'BASICO', 'Eletronuclear');
INSERT INTO conteudo (titulo, categoria, descricao, nivel, fonte) VALUES
    ('Angra dos Reis: usinas nucleares no Brasil', 'ENERGIA', 'O Brasil possui usinas nucleares em operacao na Central Nuclear Almirante Alvaro Alberto, em Angra dos Reis, no Rio de Janeiro.', 'BASICO', 'Eletronuclear');